import{u as f,b as v}from"./data_collaboration-BwD9_jUr.js";function e({id:s,label:n,icon:i,kind:r,niveau:a,why:o,system:u,choice:l,senior:c,errors:p,invariants:d,practice:m,verification:g}){return{id:s,label:n,icon:i,kind:r,osLabel:"Universel",niveau:a,sections:v({why:o,system:u,choice:l,senior:c,errors:p,invariants:d,practice:m,verification:g})}}function t(s){return f("D","Design",s)}const h=t({id:"design-D01",number:21,title:"Expérience Utilisateur",subtitle:"Concevoir des expériences lisibles, actionnables et alignées sur les vrais usages",badge:"Fiche D01 — Vision Systémique",meta:["5 nœuds · universel"],readingTime:"20 min",description:"Comprendre l'UX réelle, la hiérarchie de l'information, les flux, la charge cognitive, le feedback et les affordances.",accent:"fondement",nodes:{uxRealite:e({id:"uxRealite",label:"Ce qu'est vraiment l'UX",icon:"👁",kind:"fondement",niveau:"Fondation",why:"Une personne arrive avec une intention simple, mais le produit lui impose ses écrans, son vocabulaire interne, ses détours et ses ambiguïtés. Elle voulait réserver, comprendre, payer ou apprendre ; elle se retrouve à deviner où cliquer, à corriger des erreurs obscures, ou à abandonner sans savoir si le problème vient d'elle. L'UX existe pour réduire cette distance entre intention humaine et système construit.",system:`L'UX transforme la compréhension du problème réel <span class="ref-fiche">→ C01</span> et des utilisateurs <span class="ref-fiche">→ C02</span> en expérience vécue. Elle conditionne ensuite la hiérarchie de l'information <span class="ref-fiche">→ D01</span>, les flux <span class="ref-fiche">→ D01</span>, les composants <span class="ref-fiche">→ D03</span> et les choix visuels <span class="ref-fiche">→ D02</span> : si l'expérience visée est floue, chaque décision d'interface devient décorative.`,choice:"Le choix conscient consiste à décider quel niveau d'UX on traite. L'UX Research clarifie les besoins et comportements avant la solution ; l'Interaction Design rend le chemin utilisable écran par écran ; le Service Design regarde l'expérience complète, y compris les emails, le support et les moments hors écran. Un petit produit peut commencer par le flux principal, mais un produit critique doit considérer tout le parcours.",senior:`Un designer expérimenté ne demande pas seulement si l'utilisateur aime l'interface : il observe s'il réussit la tâche, où son regard hésite, où il reformule mentalement les libellés, et quel contournement il invente. Il redoute les compliments vagues parce qu'ils masquent souvent une expérience mal comprise. Le signal fort n'est pas "c'est joli", c'est une tâche terminée sans explication extérieure.`,errors:"<p><strong>Pattern 1 — L'UX cosmétique :</strong> sous pression de livraison, l'équipe traite l'UX comme une couche visuelle ajoutée à la fin. Le problème vient du biais de visibilité : ce qui se voit en capture d'écran semble plus réel que les hésitations invisibles de l'utilisateur.</p><p><strong>Pattern 2 — L'utilisateur miroir :</strong> le concepteur projette son propre niveau de connaissance sur l'utilisateur et trouve le produit évident. Ce pattern apparaît parce que plus on connaît un système, plus il devient difficile d'imaginer l'ignorance initiale.</p><p><strong>Pattern 3 — Le succès déclaratif :</strong> on croit une expérience validée parce que les gens disent aimer le concept. La pression d'obtenir des retours positifs fait oublier que les comportements observés valent plus que les opinions polies.</p>",invariants:"<p>Les modes d'interaction changent, mais l'utilisateur reste une personne qui poursuit une intention sous contraintes de temps, d'attention et de contexte. <strong>Ce qui change :</strong> les devices, les conventions visuelles et les outils de prototypage. <strong>Ce qui ne change pas :</strong> une bonne expérience réduit toujours l'écart entre ce que l'utilisateur veut accomplir et ce que le système lui demande de comprendre.</p>",practice:{titre:"Auditer l'expérience d'une tâche réelle",etapes:["Choisis un produit courant et une tâche précise, par exemple créer un compte, réserver un créneau ou retrouver une facture.","Réalise la tâche sans utiliser ta mémoire du produit et note chaque moment d'hésitation, de retour arrière ou de doute.","Classe chaque friction : compréhension, navigation, saisie, attente, erreur ou confiance.","Formule une hypothèse de correction pour la friction la plus coûteuse."],output:"Tableau avec la tâche, les étapes, les frictions classées, et une hypothèse de correction prioritaire.",critere:"L'audit est réussi si une autre personne peut refaire la tâche et reconnaître au moins une des frictions que tu as nommées.",piege:"Auditer l'interface comme une image statique. L'UX se révèle dans l'enchaînement des actions, pas dans une capture d'écran isolée."},verification:["Explique pourquoi une interface visuellement propre peut quand même produire une mauvaise UX.",`Un testeur dit "j'aime bien" mais met 6 minutes à trouver comment annuler son abonnement. Quel signal dois-tu croire et que dois-tu investiguer ?`,"Pourquoi l'UX reste-t-elle importante même si les technologies d'interaction changent complètement ?"]}),hierarchieInfo:e({id:"hierarchieInfo",label:"Hiérarchie de l'information",icon:"⬡",kind:"fondement",niveau:"Fondation",why:"Un écran qui donne tout avec la même intensité oblige l'utilisateur à faire le tri lui-même. Il scanne, ne sait pas où commencer, confond l'action principale avec les options secondaires, puis ralentit ou clique au hasard. La hiérarchie existe parce que l'attention humaine est sélective : une interface doit dire quoi regarder d'abord.",system:`La hiérarchie traduit les priorités du problème <span class="ref-fiche">→ C01</span> dans la structure de l'écran. Elle guide les flux utilisateur <span class="ref-fiche">→ D01</span>, réduit la charge cognitive <span class="ref-fiche">→ D01</span>, et donne aux principes visuels <span class="ref-fiche">→ D02</span> un rôle fonctionnel : taille, contraste et espacement servent une priorité, pas une décoration.`,choice:"Les signaux de hiérarchie sont complémentaires. La taille attire fortement mais peut devenir bruyante ; le contraste distingue les actions critiques mais perd son effet s'il est utilisé partout ; la position guide le scan selon les conventions de lecture ; l'espacement regroupe ou sépare les idées. Le bon choix dépend de l'intention : orienter, rassurer, comparer ou faire agir.",senior:`Un designer expérimenté limite volontairement le nombre de niveaux perceptibles. Il utilise le test du flou : si l'interface floutée ne montre plus clairement le titre, l'action principale et les groupes de contenu, la hiérarchie dépend trop du texte. Il redoute les écrans où chaque équipe a obtenu son élément "important" au même niveau.`,errors:"<p><strong>Pattern 1 — La démocratie visuelle :</strong> chaque stakeholder réclame la même importance pour son contenu, donc tout devient gros, coloré et prioritaire. La cause est politique : personne ne veut accepter que son information soit secondaire.</p><p><strong>Pattern 2 — Le CTA rival :</strong> plusieurs actions principales semblent équivalentes alors qu'elles n'ont pas la même valeur utilisateur. Ce pattern vient de la confusion entre options disponibles et décision à guider.</p><p><strong>Pattern 3 — La hiérarchie par décoration :</strong> on ajoute couleurs et tailles après coup pour rendre l'écran plus vivant, sans réexaminer l'ordre réel des décisions. Le biais esthétique masque un problème d'architecture d'information.</p>",invariants:"<p>Les styles passent de mode, mais la perception cherche toujours des différences de poids pour organiser l'information. <strong>Ce qui change :</strong> les typographies, palettes et conventions de layout. <strong>Ce qui ne change pas :</strong> sans signaux de priorité cohérents, l'attention humaine doit reconstruire elle-même l'ordre de lecture.</p>",practice:{titre:"Tester une hiérarchie avec le flou",etapes:["Choisis un écran riche en contenu : page d'accueil, tableau de bord ou page produit.","Floute mentalement ou visuellement la capture jusqu'à ne plus lire le texte.","Note les trois éléments qui dominent encore et compare-les à l'objectif utilisateur principal.","Propose un changement de taille, contraste, position ou espacement pour corriger le premier décalage."],output:"Capture annotée avec niveau 1, niveau 2, niveau 3 et correction proposée.",critere:"La hiérarchie est correcte si une personne peut prédire l'action principale sans lire tout le contenu.",piege:"Confondre priorité business et priorité perceptive. Une information peut être importante pour l'entreprise sans devoir dominer le premier regard."},verification:["Pourquoi une page avec quatre boutons primaires crée-t-elle une mauvaise hiérarchie ?","Tu floutes une page de pricing et le premier élément visible est un badge promotionnel, pas les offres. Que déduis-tu ?","Pourquoi la hiérarchie reste-t-elle un invariant même si les styles visuels changent ?"]}),fluxUtilisateur:e({id:"fluxUtilisateur",label:"Flux utilisateur",icon:"→",kind:"pattern",niveau:"Fondation",why:"Un utilisateur ne vit jamais un écran seul : il arrive de quelque part, prend une décision, traverse une étape, se trompe parfois, puis attend une confirmation. Quand on conçoit écran par écran, les transitions deviennent des trous noirs : retour impossible, étape inutile, erreur non prévue. Le flux existe pour concevoir la progression complète.",system:'Le flux matérialise les besoins utilisateur issus de <span class="ref-fiche">→ C02</span> et le périmètre décidé en <span class="ref-fiche">→ C03</span>. Il organise la hiérarchie de chaque écran <span class="ref-fiche">→ D01</span>, détermine les composants nécessaires <span class="ref-fiche">→ D03</span>, et révèle les mesures à suivre ensuite <span class="ref-fiche">→ C06</span> : abandon, erreur, reprise et réussite.',choice:"Un user flow montre les étapes et décisions pour raisonner vite ; un wireflow ajoute les écrans pour vérifier la continuité ; un prototype interactif teste le rythme et les incompréhensions ; une journey map inclut les émotions et points de contact hors produit. Plus l'enjeu est comportemental, plus il faut aller vers prototype ou journey map.",senior:"Un designer expérimenté commence rarement par le happy path seul. Il anticipe les retours arrière, les interruptions, les données manquantes, les erreurs de paiement, les sessions expirées et les reprises plus tard. Il sait qu'un flux est robuste quand l'utilisateur peut se tromper sans se sentir piégé.",errors:"<p><strong>Pattern 1 — Le tunnel parfait :</strong> le flux est dessiné uniquement pour l'utilisateur motivé, informé et sans erreur. La cause est l'optimisme de conception : on imagine le comportement désiré au lieu du comportement probable.</p><p><strong>Pattern 2 — L'écran orphelin :</strong> un écran est bien conçu seul mais ne dit pas clairement d'où l'on vient ni où repartir. Ce pattern apparaît quand les maquettes sont évaluées comme des planches graphiques plutôt que comme des séquences.</p><p><strong>Pattern 3 — La friction invisible :</strong> une étape semble petite pour l'équipe mais coûteuse pour l'utilisateur, comme chercher une information externe ou vérifier un email. La cause est la sous-estimation du contexte réel d'usage.</p>",invariants:"<p>Les écrans, assistants vocaux ou gestes changent la forme du parcours, mais pas le fait qu'une action se déroule dans le temps. <strong>Ce qui change :</strong> les supports, transitions et patterns de navigation. <strong>Ce qui ne change pas :</strong> chaque étape inutile ou ambiguë augmente la probabilité d'abandon.</p>",practice:{titre:"Cartographier un flux avec échecs",etapes:["Choisis un objectif précis, comme changer un mot de passe ou réserver une livraison.","Liste le happy path en étapes courtes, avec une seule décision par étape.","Ajoute au moins trois chemins d'échec : information absente, erreur de saisie, abandon ou retour arrière.","Indique pour chaque échec comment l'interface permet de comprendre, corriger et reprendre."],output:"Schéma de flux avec happy path, trois chemins d'échec et mécanismes de reprise.",critere:"Le flux est exploitable si aucune erreur ne se termine par une impasse ou un message sans prochaine action.",piege:"Supprimer les chemins d'échec pour rendre le schéma plus propre. Un flux propre mais irréaliste ne protège pas l'expérience réelle."},verification:["Pourquoi faut-il dessiner le flux avant de détailler les composants ?","Un onboarding perd 40% des utilisateurs après la demande de numéro de téléphone. Quelles hypothèses de flux dois-tu tester ?","Quelle différence durable y a-t-il entre un happy path et un flux utilisateur complet ?"]}),chargeCognitive:e({id:"chargeCognitive",label:"Charge cognitive",icon:"🧠",kind:"fondement",niveau:"Fondation",why:"Un écran peut être techniquement complet et mentalement épuisant. L'utilisateur doit retenir une règle, comparer trop d'options, comprendre des libellés abstraits, puis décider sans savoir ce qui compte. Quand l'effort mental dépasse la valeur perçue, il ralentit, reporte ou abandonne.",system:`La charge cognitive dépend de la hiérarchie <span class="ref-fiche">→ D01</span>, du nombre d'étapes du flux <span class="ref-fiche">→ D01</span>, de la clarté typographique <span class="ref-fiche">→ D02</span> et de la qualité des formulaires <span class="ref-fiche">→ D03</span>. Elle relie directement design et apprentissage : une interface doit externaliser l'information que l'utilisateur ne devrait pas mémoriser.`,choice:"Plusieurs leviers réduisent la charge. Le chunking regroupe les informations liées ; la divulgation progressive cache ce qui n'est utile que plus tard ; les conventions connues remplacent l'apprentissage ; la reconnaissance évite de mémoriser. La loi de Hick rappelle qu'augmenter le nombre d'options simultanées ralentit la décision, surtout quand les options se ressemblent.",senior:"Un designer expérimenté distingue la complexité nécessaire de la complexité ajoutée. Remplir une déclaration fiscale est intrinsèquement complexe ; demander à l'utilisateur de mémoriser un code reçu trois écrans plus tôt est une complexité extrinsèque créée par l'interface. Il ne promet pas toujours une interface courte : il cherche une interface qui porte l'effort au bon endroit.",errors:"<p><strong>Pattern 1 — Le dashboard cockpit :</strong> tout est affiché pour montrer la puissance du produit, mais personne ne sait quoi regarder. La cause est le biais d'exhaustivité : confondre disponibilité de l'information et utilité au moment présent.</p><p><strong>Pattern 2 — La mémoire sous-traitée :</strong> l'interface force l'utilisateur à retenir un prix, un code, une option ou une règle d'un écran à l'autre. Ce pattern vient souvent d'une architecture interne plus simple pour l'équipe mais plus coûteuse pour l'utilisateur.</p><p><strong>Pattern 3 — La simplification destructive :</strong> on retire des informations nécessaires au nom de la simplicité, puis l'utilisateur perd confiance. La cause est une confusion entre réduire la charge et cacher le contexte indispensable.</p>",invariants:"<p>Les interfaces peuvent devenir plus intelligentes, mais la mémoire de travail humaine reste limitée. <strong>Ce qui change :</strong> les patterns de disclosure, d'automatisation et d'aide contextuelle. <strong>Ce qui ne change pas :</strong> une interface qui force l'utilisateur à retenir, comparer et deviner au-delà de sa mémoire de travail augmente toujours erreurs et abandon.</p>",practice:{titre:"Repérer la charge cognitive d'un flux",etapes:["Choisis un flux de 4 à 8 étapes.","Pour chaque étape, liste ce que l'utilisateur doit lire, décider et mémoriser.","Identifie les charges intrinsèques nécessaires et les charges extrinsèques créées par l'interface.","Propose une correction pour supprimer une charge extrinsèque sans retirer une information nécessaire."],output:"Tableau étape par étape avec lecture, décision, mémoire, type de charge et correction proposée.",critere:"La correction est bonne si elle réduit un effort mental sans rendre la décision moins informée.",piege:"Croire que moins d'éléments signifie toujours moins de charge. Une information absente peut créer plus d'effort qu'une information bien placée."},verification:["Explique la différence entre complexité nécessaire et complexité ajoutée par l'interface.","Un écran de choix d'abonnement affiche 12 options presque identiques. Comment la loi de Hick t'aide-t-elle à diagnostiquer le problème ?","Pourquoi la mémoire de travail reste-t-elle un invariant de design, même avec de nouveaux outils ?"]}),feedbackAffordance:e({id:"feedbackAffordance",label:"Feedback et affordances",icon:"↩",kind:"pattern",niveau:"Fondation",why:"Un utilisateur voit un élément, se demande s'il peut agir dessus, clique, puis attend de savoir si quelque chose s'est passé. Si l'interface ne suggère pas l'action possible ou ne répond pas après l'action, l'utilisateur répète, doute ou abandonne. Feedback et affordances existent pour fermer cette boucle d'incertitude.",system:`Les affordances rendent les composants <span class="ref-fiche">→ D03</span> compréhensibles avant l'action ; le feedback rend les états d'interface <span class="ref-fiche">→ D03</span> compréhensibles après l'action. Ils s'appuient sur le contraste et la couleur <span class="ref-fiche">→ D02</span>, mais doivent aussi rester accessibles quand la couleur ne suffit pas.`,choice:"Une affordance peut être visuelle (forme de bouton), textuelle (verbe clair), spatiale (zone touchable) ou conventionnelle (icône connue). Le feedback peut être immédiat pour confirmer un clic, progressif pour une attente, de résultat pour une réussite, ou correctif pour une erreur. Le choix dépend du risque : plus l'action est critique, plus le feedback doit être explicite.",senior:"Un designer expérimenté applique les seuils de réponse de Nielsen : sous 100 ms, l'action paraît instantanée ; entre 100 ms et 1 s, le flux reste fluide ; au-delà de 1 s, il faut signaler l'attente ; au-delà de 10 s, il faut une progression ou une alternative. Il anticipe aussi le focus clavier et le lecteur d'écran : un feedback visible mais muet n'est pas un feedback complet.",errors:"<p><strong>Pattern 1 — Le bouton caméléon :</strong> une action ressemble à du texte ou à une décoration, donc l'utilisateur ne la perçoit pas comme interactive. La cause est souvent une recherche de minimalisme qui efface les signaux d'action.</p><p><strong>Pattern 2 — Le clic sans écho :</strong> après une action, rien ne change immédiatement, donc l'utilisateur reclique ou pense que le système est cassé. Ce pattern vient de la sous-estimation du besoin de confirmation temporelle.</p><p><strong>Pattern 3 — L'erreur tribunal :</strong> le message dit seulement que l'utilisateur a échoué, sans expliquer quoi corriger ni comment reprendre. La cause est une vision technique de l'erreur plutôt qu'une vision de récupération utilisateur.</p>",invariants:"<p>Les formes d'interaction changent, mais l'humain cherche toujours à prédire ce qui est possible et à vérifier l'effet de son action. <strong>Ce qui change :</strong> les micro-interactions, les devices et les conventions de feedback. <strong>Ce qui ne change pas :</strong> agir sans retour perceptible crée toujours doute, répétition inutile et perte de confiance.</p>",practice:{titre:"Auditer les boucles action-retour",etapes:["Choisis un écran avec au moins cinq éléments interactifs.","Pour chacun, note comment l'utilisateur sait avant l'action qu'il peut interagir.","Simule l'action et note le feedback immédiat, le feedback d'attente et le feedback de résultat ou d'erreur.","Corrige l'élément le plus ambigu avec un signal avant action et un retour après action."],output:"Audit de cinq boucles action-retour avec ambiguïtés et correction prioritaire.",critere:"Chaque boucle est correcte si l'utilisateur peut répondre à deux questions : que puis-je faire ici, et que vient-il de se passer ?",piege:"Concevoir le feedback uniquement pour la réussite. Les erreurs et attentes sont les moments où l'utilisateur a le plus besoin de retour."},verification:["Explique la différence entre affordance et feedback avec un exemple concret.","Après un paiement, rien ne se passe pendant 3 secondes. Quel feedback dois-tu prévoir et pourquoi ?","Pourquoi un feedback doit-il rester utile même si la couleur, l'animation ou le son ne sont pas perçus ?"]})},maps:{universel:{viewBox:"0 0 820 270",nodes:[{id:"uxRealite",x:10,y:100,w:140,h:65},{id:"hierarchieInfo",x:200,y:100,w:155,h:65},{id:"fluxUtilisateur",x:410,y:40,w:145,h:65},{id:"chargeCognitive",x:410,y:165,w:145,h:65},{id:"feedbackAffordance",x:620,y:100,w:185,h:65}],edges:[{x1:150,y1:132,x2:198,y2:132,label:"fonde"},{x1:355,y1:112,x2:408,y2:72,label:"structure"},{x1:355,y1:150,x2:408,y2:188,label:"réduit"},{x1:555,y1:72,x2:618,y2:118,label:"exprime"},{x1:555,y1:192,x2:618,y2:150,label:"exprime"}]}}}),q=t({id:"design-D02",number:22,title:"Principes Visuels",subtitle:"Rendre l'information lisible, hiérarchisée, cohérente et accessible",badge:"Fiche D02 — Vision Systémique",meta:["5 nœuds · universel"],readingTime:"25 min",description:"Typographie, couleur, espacement, contraste, accessibilité et consistance visuelle comme système de lisibilité.",accent:"visuel",nodes:{typographie:e({id:"typographie",label:"Typographie",icon:"Aa",kind:"visuel",niveau:"Fondation",why:"Un texte peut contenir la bonne information et rester inutilisable si l'œil doit lutter pour le lire : lettres trop petites, lignes trop longues, interlignage serré, trop de styles concurrents. La typographie existe pour réduire l'effort de lecture avant même que le contenu soit compris.",system:'La typographie exprime la hiérarchie construite en D01 <span class="ref-fiche">→ D01</span> et devient une règle réutilisable dans les composants <span class="ref-fiche">→ D03</span>. Elle doit ensuite être codifiée en tokens typographiques <span class="ref-fiche">→ D04</span> pour rester cohérente entre design et code.',choice:"Corps de texte lisible : 16px minimum sur le web, line-height autour de 1.4-1.6, longueur de ligne idéale autour de 60-75 caractères. Une échelle typographique modulaire est adaptée aux produits denses ; une échelle plus expressive convient aux pages éditoriales ou marketing. Le compromis réel : lisibilité, densité d'information, personnalité de marque.",senior:"Un designer expérimenté ne choisit pas une police en regardant un mot isolé. Il vérifie un paragraphe long, un label court, un nombre, un message d'erreur et un écran mobile. Il redoute surtout les styles orphelins : un H5, un caption ou un label qui n'a pas de rôle clair finit toujours par créer de l'incohérence.",errors:"<p><strong>Pattern 1 — La police vitrine :</strong> on choisit une police parce qu'elle a du caractère en grand, puis elle fatigue en texte courant.</p><p><strong>Pattern 2 — L'échelle improvisée :</strong> chaque écran ajoute une taille de texte locale, jusqu'à ce que la hiérarchie devienne impossible à maintenir.</p><p><strong>Pattern 3 — La ligne tunnel :</strong> les lignes dépassent 90 caractères ; l'utilisateur perd le début de la ligne suivante et ralentit sans comprendre pourquoi.</p>",invariants:"<p>La lecture dépend de contraintes perceptives : taille apparente, rythme vertical, longueur de ligne, contraste et familiarité des formes. <strong>Ce qui change :</strong> les polices, les modes et les moteurs de rendu. <strong>Ce qui ne change pas :</strong> un texte lisible minimise l'effort de décodage pour libérer l'attention sur le sens.</p>",practice:{titre:"Créer une échelle typographique minimale",etapes:["Choisis un écran contenant titre, paragraphe, label et aide.","Définis 4 rôles typographiques maximum : titre, sous-titre, body, caption/label.","Vérifie body à 16px minimum, line-height 1.4-1.6 et lignes de 60-75 caractères.","Note pour chaque style son rôle et un exemple d'usage."],output:"Une échelle typographique de 4 styles avec taille, line-height, rôle et exemple.",critere:"Si deux styles ont le même rôle perceptif, fusionne-les. Si un paragraphe dépasse 75 caractères par ligne, ajuste largeur ou taille.",piege:"Créer des tailles pour obtenir un rendu joli localement au lieu de créer des rôles réutilisables."},verification:["Pourquoi 16px est-il un bon minimum pour le corps de texte web ?","Sur une page d'article mobile, les lignes font 95 caractères et le line-height est 1.1. Quels problèmes de lecture observes-tu ?","Quel trade-off existe entre densité d'information et confort typographique ?"]}),couleur:e({id:"couleur",label:"Couleur",icon:"🎨",kind:"visuel",niveau:"Fondation",why:"Quand toutes les couleurs servent à décorer, plus aucune ne signale vraiment l'action, l'état ou le danger. L'utilisateur ne sait plus ce qui est cliquable, prioritaire, positif ou destructif. La couleur existe comme système de communication avant d'être un choix esthétique.",system:`La couleur soutient la hiérarchie D01 <span class="ref-fiche">→ D01</span>, signale les états des composants <span class="ref-fiche">→ D03</span>, puis devient un ensemble de tokens sémantiques <span class="ref-fiche">→ D04</span>. Elle ne doit jamais porter seule une information critique, car l'accessibilité dépend aussi du texte, de l'icône et de la forme.`,choice:"Une palette produit distingue généralement couleurs de marque, couleurs neutres, couleurs d'action et couleurs d'état. La règle 60-30-10 aide à doser : 60% neutre/dominant, 30% secondaire, 10% accent. Une interface métier gagne souvent à rester sobre ; une expérience éditoriale peut être plus expressive si les rôles restent clairs.",senior:"Un designer expérimenté teste immédiatement les conflits sémantiques : une marque verte avec une action destructive, un rouge utilisé comme accent marketing, un bleu utilisé à la fois pour lien et information passive. Il anticipe aussi dark mode, daltonisme et états disabled avant de figer la palette.",errors:"<p><strong>Pattern 1 — L'arc-en-ciel fonctionnel :</strong> chaque catégorie reçoit une couleur différente jusqu'à dépasser ce que l'utilisateur peut mémoriser.</p><p><strong>Pattern 2 — Le rouge décoratif :</strong> une couleur culturellement associée à l'erreur est utilisée pour attirer l'œil ; les vrais dangers perdent leur signal.</p><p><strong>Pattern 3 — L'information uniquement colorée :</strong> un statut vert/rouge sans texte ni icône devient invisible pour une partie des utilisateurs.</p>",invariants:"<p>La couleur est perçue relativement : contraste, contexte, culture et déficiences visuelles changent sa lecture. <strong>Ce qui change :</strong> les tendances de palette et les identités de marque. <strong>Ce qui ne change pas :</strong> une couleur d'interface doit avoir un rôle reconnaissable et ne jamais être le seul porteur d'une information critique.</p>",practice:{titre:"Construire une palette sémantique minimale",etapes:["Liste les rôles nécessaires : texte, surface, action primaire, succès, warning, erreur, focus.","Assigne une couleur ou nuance à chaque rôle, pas à chaque écran.","Vérifie que l'action destructive reste distincte de la couleur de marque.","Ajoute pour chaque statut un texte ou une icône complémentaire."],output:"Une palette sémantique avec rôles, exemples d'usage et règle de non-usage.",critere:"Si une couleur apparaît sans rôle nommé, supprime-la ou rattache-la à un rôle existant.",piege:"Commencer par des couleurs aimées plutôt que par les messages que l'interface doit transmettre."},verification:["Explique la règle 60-30-10 et son intérêt dans une interface.","Ta marque est verte mais tes boutons de validation sont verts aussi. Comment évites-tu la confusion avec succès/état ?","Pourquoi la couleur seule n'est-elle jamais un invariant suffisant pour transmettre une information ?"]}),espacementGrille:e({id:"espacementGrille",label:"Espacement et grille",icon:"⊞",kind:"visuel",niveau:"Fondation",why:"Place deux éléments trop près et le cerveau les regroupe, même si le texte dit autre chose. Éloigne deux éléments d'une même action et l'utilisateur croit qu'ils appartiennent à deux zones différentes. L'espacement sert de syntaxe visuelle : il indique les groupes, les séparations et le rythme avant les mots.",system:`L'espacement applique la loi de proximité issue des fondements UX <span class="ref-fiche">→ D01</span> et structure les composants <span class="ref-fiche">→ D03</span>. Une échelle d'espacement doit devenir tokenisée <span class="ref-fiche">→ D04</span> pour éviter les corrections pixel par pixel.`,choice:"Une grille 8pt est efficace pour la plupart des interfaces web et mobile ; une grille 4pt offre plus de finesse pour les petits composants. Les layouts éditoriaux peuvent utiliser des grilles colonnes plus expressives. Le trade-off : vitesse de décision et cohérence contre précision locale.",senior:"Un designer expérimenté regarde les groupes avant les composants. Si les espacements internes et externes sont confondus, l'utilisateur ne sait plus ce qui appartient à quoi. Il vérifie aussi la densité : une app métier peut être dense, mais jamais au point de détruire les regroupements perceptifs.",errors:"<p><strong>Pattern 1 — Le padding au feeling :</strong> chaque espacement est ajusté à l'œil, sans échelle. Le fichier paraît bon localement et incohérent globalement.</p><p><strong>Pattern 2 — L'égalité qui brouille :</strong> tout reçoit le même espace ; les groupes et séparations ont la même force visuelle.</p><p><strong>Pattern 3 — La grille prison :</strong> on respecte une grille même quand elle nuit à la lecture ou au rythme réel du contenu.</p>",invariants:"<p>La perception groupe par proximité avant d'analyser le contenu. L'espace peut donc expliquer une relation ou la rendre fausse. <strong>Ce qui change :</strong> les grilles, densités et systèmes d'unités. <strong>Ce qui ne change pas :</strong> l'espacement guide toujours la perception des groupes, des séparations et du rythme.</p>",practice:{titre:"Définir une échelle d'espacement",etapes:["Choisis un écran contenant cartes, titres, champs et actions.","Note tous les espacements utilisés et regroupe les valeurs proches.","Réduis-les à une échelle 4 ou 8pt avec 5-7 valeurs maximum.","Réapplique l'échelle en distinguant espace interne, espace entre éléments liés et espace entre sections."],output:"Une échelle d'espacement avec valeurs, rôles et écran annoté.",critere:"Deux éléments liés doivent être plus proches entre eux que d'une autre section. Si ce n'est pas visible sans lire, l'échelle échoue.",piege:"Traiter l'espace comme une finition esthétique plutôt que comme une information structurelle."},verification:["Explique la loi de proximité avec un exemple d'interface.","Un formulaire a le même espace entre label/champ et entre deux groupes de champs. Que comprend mal l'utilisateur ?","Quel trade-off existe entre grille stricte et ajustement optique ?"]}),contrasteAccessibilite:e({id:"contrasteAccessibilite",label:"Contraste et accessibilité",icon:"◑",kind:"fondement",niveau:"Fondation",why:"Une interface peut être élégante et illisible pour une partie de ses utilisateurs : texte gris trop pâle, focus invisible, zone tactile minuscule, erreur indiquée seulement par rouge. L'accessibilité existe parce que les conditions réelles d'usage ne ressemblent pas au grand écran calibré du designer.",system:`Le contraste rend la typographie et la couleur utilisables. Il conditionne les composants D03 <span class="ref-fiche">→ D03</span> : focus, erreurs, disabled, zones tactiles. Il doit être documenté dans le système D04 <span class="ref-fiche">→ D04</span> pour que l'accessibilité ne dépende pas de vérifications manuelles tardives.`,choice:"WCAG AA demande 4.5:1 pour le texte normal et 3:1 pour les grands textes et éléments graphiques essentiels. AAA est plus strict mais pas toujours réaliste. Les zones tactiles mobiles doivent viser au moins 44x44px. Le choix n'est pas accessibilité contre esthétique : c'est esthétique sous contraintes réelles.",senior:"Un designer expérimenté vérifie contraste, focus clavier, taille tactile et messages d'erreur avant de présenter une maquette comme prête. Il utilise un outil type WebAIM Contrast Checker ou les audits navigateur, mais sait que l'outil ne juge pas l'intention : un ratio valide ne suffit pas si l'information dépend seulement de la couleur.",errors:"<p><strong>Pattern 1 — Le gris premium :</strong> on baisse le contraste pour obtenir une esthétique douce, puis le texte devient illisible en lumière réelle.</p><p><strong>Pattern 2 — Le focus sacrifié :</strong> l'état focus est supprimé parce qu'il est jugé laid. La navigation clavier disparaît.</p><p><strong>Pattern 3 — L'accessibilité patch :</strong> on corrige contraste et labels après développement, quand chaque correction touche design, code et QA.</p>",invariants:"<p>L'accessibilité repose sur des constantes humaines : vision variable, motricité imparfaite, attention limitée, contextes lumineux changeants. <strong>Ce qui change :</strong> les standards, outils d'audit et devices. <strong>Ce qui ne change pas :</strong> une interface robuste doit rester perceptible, actionnable et compréhensible hors conditions idéales.</p>",practice:{titre:"Vérifier une interface contre WCAG AA",etapes:["Choisis un écran avec texte, bouton, lien, erreur et champ de formulaire.","Vérifie les contrastes : 4.5:1 texte normal, 3:1 grand texte ou élément UI essentiel.","Vérifie que les cibles tactiles principales atteignent environ 44x44px.","Note les informations transmises uniquement par couleur et ajoute texte, icône ou forme."],output:"Audit accessibilité avec ratios, zones tactiles, problèmes et corrections proposées.",critere:"Chaque problème doit avoir une correction concrète. Si tu écris seulement 'améliorer contraste', l'audit n'est pas terminé.",piege:"Croire qu'un score automatique remplace une revue humaine des états, textes, focus et usages réels."},verification:["Quels ratios WCAG AA faut-il viser pour texte normal et grand texte ?","Un bouton rouge sans texte indique une erreur dans un tableau. Pourquoi est-ce insuffisant et comment corriges-tu ?","Pourquoi l'accessibilité est-elle un invariant de qualité plutôt qu'un mode séparé ?"]}),consistance:e({id:"consistance",label:"Consistance visuelle",icon:"⊡",kind:"systeme",niveau:"Fondation",why:"Quand deux boutons identiques font des choses différentes, l'utilisateur devient prudent. Quand deux éléments différents font la même chose, il hésite. L'inconsistance force à réapprendre l'interface écran par écran et augmente la charge cognitive sans ajouter de valeur.",system:'La consistance stabilise les principes visuels de D02 et prépare les composants de D03 <span class="ref-fiche">→ D03</span>. Elle devient maintenable seulement avec un design system et des tokens <span class="ref-fiche">→ D04</span>. Elle dépend aussi des conventions externes : un produit cohérent avec lui-même mais incohérent avec le web reste coûteux à apprendre.',choice:"Il faut distinguer consistance interne, conventions externes et différenciation. La consistance interne rend le produit prévisible ; les conventions externes réduisent l'apprentissage ; la différenciation se justifie seulement quand elle améliore un moment clé.",senior:"Un designer expérimenté ne défend pas la consistance comme une religion. Il demande : est-ce que cette variation aide l'utilisateur à comprendre une différence réelle ? Si oui, elle peut être utile. Sinon, elle est une dette cognitive et systémique.",errors:"<p><strong>Pattern 1 — L'exception séduisante :</strong> un écran important reçoit un traitement spécial, puis l'exception devient un précédent que d'autres écrans imitent mal.</p><p><strong>Pattern 2 — La cohérence contre convention :</strong> l'équipe invente un pattern cohérent en interne mais contraire aux habitudes du web. L'utilisateur paie le coût d'apprentissage.</p><p><strong>Pattern 3 — L'uniformité aveugle :</strong> tout est rendu identique, même quand des différences de risque ou de priorité devraient être visibles.</p>",invariants:"<p>Le cerveau apprend des régularités et prédit la suite à partir d'elles. La consistance réduit l'effort en rendant ces prédictions fiables. <strong>Ce qui change :</strong> les styles, conventions et composants disponibles. <strong>Ce qui ne change pas :</strong> une interface prévisible demande moins d'énergie qu'une interface qui oblige à réinterpréter chaque écran.</p>",practice:{titre:"Auditer la consistance d'un flux",etapes:["Choisis trois écrans du même flux.","Liste les boutons, liens, titres, espacements, messages d'erreur et états.","Repère les variations qui n'ont pas de raison utilisateur.","Documente une règle pour chaque variation à supprimer ou conserver."],output:"Audit de consistance avec variations, justification utilisateur et règles proposées.",critere:"Une variation conservée doit signaler une différence réelle de sens, priorité ou risque. Sinon elle doit disparaître.",piege:"Confondre consistance et uniformité : l'objectif n'est pas que tout se ressemble, mais que les différences signifient quelque chose."},verification:["Quelle différence fais-tu entre consistance et uniformité ?","Un écran marketing utilise un bouton violet alors que l'app utilise bleu pour l'action principale. Comment décides-tu si c'est acceptable ?","Quel invariant explique pourquoi la consistance réduit la charge cognitive ?"]})},maps:{universel:{viewBox:"0 0 820 270",nodes:[{id:"typographie",x:10,y:100,w:130,h:65},{id:"couleur",x:190,y:100,w:100,h:65},{id:"espacementGrille",x:340,y:40,w:150,h:65},{id:"contrasteAccessibilite",x:340,y:165,w:200,h:65},{id:"consistance",x:600,y:100,w:130,h:65}],edges:[{x1:140,y1:132,x2:188,y2:132,label:"signale"},{x1:290,y1:112,x2:338,y2:72,label:"structure"},{x1:290,y1:150,x2:338,y2:188,label:"doit rester lisible"},{x1:490,y1:72,x2:598,y2:118,label:"stabilise"},{x1:540,y1:198,x2:598,y2:152,label:"garantit"}]}}}),b=t({id:"design-D03",number:23,title:"Composants et Patterns",subtitle:"Construire des interfaces cohérentes avec des composants, états et patterns robustes",badge:"Fiche D03 — Vision Systémique",meta:["5 nœuds · universel"],readingTime:"20 min",description:"Anatomie des composants, navigation, formulaires, états d'interface et responsive design.",accent:"pattern",nodes:{anatomieComposant:e({id:"anatomieComposant",label:"Anatomie d'un composant",icon:"◻",kind:"pattern",niveau:"Fondation",why:"Deux boutons se ressemblent au départ, puis l'un reçoit une icône, l'autre un chargement, un troisième un texte trop long, et le quatrième doit être désactivé. Sans anatomie claire, chaque écran réinvente un morceau d'interface et les développeurs devinent les règles. Un composant existe pour transformer un dessin répété en contrat réutilisable.",system:'Le composant matérialise les principes UX de <span class="ref-fiche">→ D01</span> avec les décisions visuelles de <span class="ref-fiche">→ D02</span>. Il devient ensuite une brique de design system <span class="ref-fiche">→ D04</span> et une contrainte de handoff <span class="ref-fiche">→ D04</span> : plus son anatomie est claire, moins le code doit interpréter les intentions.',choice:"Trois niveaux de composant coexistent. Un composant local sert un écran précis et évite la sur-ingénierie ; un composant réutilisable possède des variants, états et règles documentées ; un composant composé expose des slots ou sous-parties configurables pour des cas complexes. Atomic Design de Brad Frost aide à penser l'échelle : atomes, molécules, organismes, templates, pages.",senior:"Un designer expérimenté teste un composant contre ses limites avant de le valider : texte très long, absence d'icône, état loading, disabled, focus clavier, erreur, thème sombre, largeur mobile. Il redoute le composant qui fonctionne seulement dans la maquette parfaite, parce qu'il deviendra une dette d'interface dès le premier contenu réel.",errors:"<p><strong>Pattern 1 — Le composant carte postale :</strong> le composant est dessiné dans son état idéal seulement. La cause est la pression de produire une belle maquette, alors que la robustesse se voit dans les états moins photogéniques.</p><p><strong>Pattern 2 — L'explosion de variants :</strong> chaque léger besoin crée un nouveau variant jusqu'à rendre le composant incompréhensible. Ce pattern vient d'une absence de règles sur ce qui doit être une propriété, un slot ou un nouveau composant.</p><p><strong>Pattern 3 — Le contrat implicite :</strong> le design montre l'apparence mais ne précise pas les comportements, limites et états. Les développeurs comblent les trous, puis l'interface diverge selon les pages.</p>",invariants:"<p>Les bibliothèques changent, mais une interface réutilisable a toujours besoin de règles explicites. <strong>Ce qui change :</strong> les frameworks, conventions de composants et outils de documentation. <strong>Ce qui ne change pas :</strong> un composant fiable définit toujours sa structure, ses états, ses variants et ses limites avant d'être réutilisé.</p>",practice:{titre:"Spécifier un bouton comme composant",etapes:["Choisis un bouton réel d'une interface.","Décris son anatomie : label, icône, taille, zone tactile, couleur, état de focus.","Liste ses variants nécessaires : primaire, secondaire, danger, avec ou sans icône, pleine largeur ou contenu.","Ajoute les états default, hover, focus, active, disabled et loading, avec le comportement attendu."],output:"Fiche de composant bouton avec anatomie, variants, états et règles de contenu.",critere:"La fiche est suffisante si un développeur peut implémenter le bouton sans demander ce qui se passe en loading, disabled ou texte long.",piege:"Créer un composant global trop tôt. Si un pattern n'a qu'un seul usage stable, le transformer en composant réutilisable peut rigidifier inutilement le produit."},verification:["Pourquoi un composant est-il un contrat plutôt qu'un simple morceau de maquette ?","Ton bouton fonctionne en desktop avec un texte court, mais casse avec un texte de 38 caractères sur mobile. Quelle partie de la spécification manquait ?","Quel trade-off existe entre composant très spécifique et composant très universel ?"]}),navigation:e({id:"navigation",label:"Patterns de navigation",icon:"☰",kind:"pattern",niveau:"Fondation",why:"Un utilisateur perdu ne pense pas que la navigation a un défaut théorique ; il doute de son emplacement, craint d'avoir raté quelque chose, ou conclut que le produit demande trop d'effort. Une bonne navigation répond en permanence à trois questions : où suis-je, où puis-je aller, comment revenir ?",system:`La navigation dépend de l'architecture d'information issue de la hiérarchie <span class="ref-fiche">→ D01</span> et du flux utilisateur <span class="ref-fiche">→ D01</span>. Elle influence les composants <span class="ref-fiche">→ D03</span>, le responsive <span class="ref-fiche">→ D03</span> et les choix visuels de repérage <span class="ref-fiche">→ D02</span> comme contraste, position et état actif.`,choice:"Une barre supérieure convient aux produits avec peu de sections principales ; une sidebar supporte des outils denses et des hiérarchies persistantes ; une bottom navigation sert les actions mobiles fréquentes, souvent 3 à 5 destinations ; un breadcrumb clarifie une profondeur ; la recherche devient navigation quand l'espace informationnel est trop large pour être parcouru manuellement.",senior:"Un designer expérimenté ne choisit pas un pattern parce qu'il est tendance : il regarde fréquence d'usage, profondeur, changement de contexte et taille d'écran. Il redoute le menu hamburger utilisé pour cacher une architecture mal priorisée. Sur mobile, il vérifie aussi que les destinations critiques restent accessibles sans chasse au menu.",errors:"<p><strong>Pattern 1 — Le hamburger pansement :</strong> on cache la complexité dans un menu au lieu de prioriser les destinations. La cause est l'évitement : il est plus facile de cacher que de décider ce qui compte.</p><p><strong>Pattern 2 — Le labyrinthe profond :</strong> l'utilisateur descend dans plusieurs niveaux sans repère clair pour remonter. Ce pattern vient souvent d'une structure calquée sur l'organisation interne plutôt que sur les tâches utilisateur.</p><p><strong>Pattern 3 — L'état actif muet :</strong> la navigation existe mais ne signale pas où l'utilisateur se trouve. La cause est une vision décorative de la nav, oubliant son rôle d'orientation.</p>",invariants:"<p>Les patterns changent avec les devices, mais l'orientation reste un besoin cognitif stable. <strong>Ce qui change :</strong> les formats de navigation, gestes et conventions selon écran. <strong>Ce qui ne change pas :</strong> un utilisateur doit toujours pouvoir comprendre sa position, ses options et son chemin de retour.</p>",practice:{titre:"Choisir un pattern de navigation",etapes:["Liste les destinations principales d'un produit réel ou imaginé.","Classe-les par fréquence d'usage et criticité utilisateur.","Choisis un pattern : top nav, sidebar, bottom nav, breadcrumb, recherche ou combinaison limitée.","Justifie le choix avec profondeur, fréquence, taille d'écran et besoin de retour."],output:"Décision de navigation argumentée avec destinations prioritaires et pattern choisi.",critere:"La décision est solide si chaque destination visible a une raison liée à l'usage, pas seulement à l'organisation interne.",piege:"Traiter la navigation comme une liste exhaustive. La navigation principale est une sélection, pas un plan complet de l'entreprise."},verification:["Quelles trois questions une bonne navigation doit-elle résoudre en continu ?",`Une app mobile bancaire cache "virement" dans un hamburger alors que c'est l'action la plus fréquente. Quel pattern proposerais-tu et pourquoi ?`,"Pourquoi la navigation dépend-elle davantage des tâches utilisateur que de la structure interne de l'entreprise ?"]}),formulaires:e({id:"formulaires",label:"Formulaires",icon:"📝",kind:"pattern",niveau:"Intermédiaire",why:"Au moment de saisir ses informations, l'utilisateur donne quelque chose au produit : temps, données personnelles, attention, parfois confiance financière. Chaque champ inutile, label flou ou erreur tardive augmente le risque d'abandon. Un bon formulaire transforme cette saisie fragile en conversation guidée.",system:`Les formulaires combinent charge cognitive <span class="ref-fiche">→ D01</span>, feedback d'erreur <span class="ref-fiche">→ D01</span>, typographie lisible <span class="ref-fiche">→ D02</span> et composants robustes <span class="ref-fiche">→ D03</span>. Ils influencent aussi la mesure produit <span class="ref-fiche">→ C06</span> : taux de complétion, abandon par champ et erreurs récurrentes.`,choice:"Un formulaire court en une page fonctionne quand la tâche est simple ; un formulaire en étapes réduit la charge pour les demandes longues ; la validation inline aide à corriger tôt mais peut devenir agressive si elle s'affiche avant la fin de saisie ; la validation à la soumission convient aux cas simples mais rend les erreurs plus coûteuses quand le formulaire est long.",senior:"Un designer expérimenté vérifie d'abord si chaque champ mérite d'exister. Il sait qu'un placeholder ne remplace jamais un label : dès que l'utilisateur saisit, l'aide disparaît. Il anticipe l'autofill, le clavier mobile, les formats locaux, les messages d'erreur récupérables et l'ordre logique de saisie.",errors:"<p><strong>Pattern 1 — Le champ par curiosité :</strong> l'équipe demande une information parce qu'elle pourrait servir plus tard. La cause est l'appétit de données, mais l'utilisateur paie immédiatement le coût de saisie.</p><p><strong>Pattern 2 — Le placeholder fantôme :</strong> le label est caché dans le placeholder, puis disparaît quand l'utilisateur écrit. Ce pattern vient d'une recherche de sobriété visuelle au détriment de la mémoire et de l'accessibilité.</p><p><strong>Pattern 3 — L'erreur punitive :</strong> l'utilisateur découvre plusieurs erreurs après soumission, avec des messages vagues. La cause est une validation pensée côté système plutôt que côté récupération utilisateur.</p>",invariants:"<p>Les champs et méthodes de saisie évoluent, mais demander une information reste un coût. <strong>Ce qui change :</strong> les contrôles, claviers, autofill et modes de validation. <strong>Ce qui ne change pas :</strong> chaque information demandée doit justifier son effort et chaque erreur doit indiquer comment reprendre.</p>",practice:{titre:"Réduire l'abandon d'un formulaire",etapes:["Choisis un formulaire de 5 champs ou plus.","Pour chaque champ, écris pourquoi l'information est nécessaire maintenant.","Identifie les champs qui peuvent être supprimés, préremplis ou déplacés plus tard.","Réécris deux messages d'erreur pour indiquer le problème, la cause probable et la correction attendue."],output:"Audit de formulaire avec justification des champs, suppressions possibles et deux messages d'erreur réécrits.",critere:"Un champ est légitime si tu peux expliquer sa valeur immédiate pour l'utilisateur ou le service rendu, pas seulement pour une analyse future.",piege:"Optimiser uniquement la longueur. Un formulaire plus court mais ambigu peut être moins performant qu'un formulaire légèrement plus long et mieux guidé."},verification:["Pourquoi un placeholder ne remplace-t-il pas un label ?","Un formulaire d'inscription perd 65% des utilisateurs au champ téléphone. Quelles hypothèses tester avant de changer la couleur du bouton ?","Quel trade-off existe entre validation inline et validation à la soumission ?"]}),etatsInterface:e({id:"etatsInterface",label:"États de l'interface",icon:"◈",kind:"pattern",niveau:"Intermédiaire",why:"Ouvre un produit en conditions réelles et l'état parfait de la maquette disparaît vite : chargement, échec, zéro résultat, données partielles, perte de connexion ou permission refusée. Si ces moments ne sont pas conçus, l'utilisateur voit du vide, du silence ou un message technique. Les états rendent le comportement du système compréhensible dans les moments imparfaits.",system:'Les états prolongent le feedback <span class="ref-fiche">→ D01</span> et structurent les composants <span class="ref-fiche">→ D03</span>. Ils doivent respecter les principes visuels <span class="ref-fiche">→ D02</span> et être documentés dans le handoff <span class="ref-fiche">→ D04</span>, car ce sont précisément les cas que le développement doit implémenter sans improviser.',choice:"Un spinner convient aux attentes brèves et indéterminées ; un skeleton est préférable quand la structure du contenu est connue ; un empty state doit expliquer la situation et proposer une prochaine action ; un error state doit dire ce qui s'est passé, si l'utilisateur peut agir, et comment reprendre ; un partial state montre ce qui est disponible sans bloquer tout l'écran.",senior:"Un designer expérimenté conçoit d'abord les états qui protègent la confiance : erreur de paiement, sauvegarde en cours, synchronisation, permission refusée, données supprimées. Il sait qu'un bon empty state n'est pas un dessin sympathique : c'est une instruction contextualisée pour passer de zéro à la première valeur.",errors:"<p><strong>Pattern 1 — Le rectangle vide :</strong> aucune donnée produit une zone blanche sans explication. La cause est que la maquette a été remplie avec des données idéales, donc personne n'a pensé au premier usage.</p><p><strong>Pattern 2 — Le spinner éternel :</strong> l'attente indéterminée devient le seul état de chargement, même quand une progression ou une alternative serait nécessaire. Ce pattern vient d'une simplification technique qui laisse l'utilisateur sans contrôle.</p><p><strong>Pattern 3 — L'erreur système brute :</strong> l'interface affiche un code ou un message backend incompréhensible. La cause est l'absence de traduction entre état technique et besoin utilisateur.</p>",invariants:"<p>Les systèmes peuvent devenir plus rapides, mais attente, absence et erreur ne disparaissent pas. <strong>Ce qui change :</strong> les indicateurs de chargement, patterns d'empty state et mécanismes de récupération. <strong>Ce qui ne change pas :</strong> l'utilisateur a toujours besoin de savoir si le système travaille, a échoué, attend une action ou n'a rien à afficher.</p>",practice:{titre:"Concevoir les cinq états d'une liste",etapes:["Choisis une liste : notifications, commandes, messages, fichiers ou résultats de recherche.","Décris l'état idéal avec données réalistes, pas parfaites.","Conçois loading, empty, error et partial state avec texte et prochaine action.","Vérifie que chaque état explique la situation sans jargon technique."],output:"Spécification des cinq états d'une liste : ideal, loading, empty, error, partial.",critere:"Chaque état est réussi si l'utilisateur peut répondre à : que se passe-t-il, est-ce grave, que puis-je faire maintenant ?",piege:"Transformer chaque empty state en message marketing. Le premier rôle d'un état vide est d'orienter, pas de décorer."},verification:["Pourquoi le skeleton est-il souvent meilleur qu'un spinner pour charger une liste structurée ?",'Une recherche renvoie zéro résultat pour "facture avril". Que doit contenir un empty state utile ?',"Pourquoi les états imparfaits sont-ils plus révélateurs de la qualité UX que l'état idéal ?"]}),responsive:e({id:"responsive",label:"Design responsive",icon:"📱",kind:"pattern",niveau:"Intermédiaire",why:"Réduire un écran desktop jusqu'à ce qu'il tienne sur mobile produit souvent une interface compressée, pas une expérience mobile. Les doigts remplacent la souris, le clavier prend la moitié de l'écran, l'attention est fragmentée, la connexion varie. Le responsive existe pour adapter priorités, interaction et layout aux contraintes réelles du contexte.",system:'Le responsive force à prioriser la hiérarchie <span class="ref-fiche">→ D01</span>, à préserver la lisibilité typographique <span class="ref-fiche">→ D02</span>, à adapter navigation et composants <span class="ref-fiche">→ D03</span>, puis à documenter ces règles dans le design system <span class="ref-fiche">→ D04</span>.',choice:"Le mobile-first oblige à commencer par l'essentiel puis enrichir ; le layout fluide adapte les dimensions entre breakpoints ; l'adaptatif prévoit des compositions différentes pour des seuils précis ; certaines interfaces denses nécessitent une version mobile repensée plutôt qu'une simple réorganisation. Les zones tactiles doivent rester au minimum proches de 44x44 px pour éviter les erreurs de toucher.",senior:"Un designer expérimenté ne teste pas seulement trois largeurs propres. Il vérifie les textes longs, le zoom système, le clavier ouvert, les zones tactiles, les orientations, les états d'erreur et les contenus réels. Il redoute les breakpoints choisis selon des devices populaires plutôt que selon le moment où le contenu casse.",errors:"<p><strong>Pattern 1 — Le desktop rétréci :</strong> l'équipe empile tout le desktop sur mobile sans repenser la priorité. La cause est la paresse de transformation : déplacer semble moins risqué que décider.</p><p><strong>Pattern 2 — Le breakpoint catalogue :</strong> les breakpoints sont choisis pour quelques modèles d'appareils, pas pour les ruptures réelles du layout. Le design casse dès qu'un écran intermédiaire ou un texte long apparaît.</p><p><strong>Pattern 3 — Le doigt oublié :</strong> les cibles tactiles restent dimensionnées pour une souris. La cause est un test effectué sur écran de design, sans interaction physique réelle.</p>",invariants:"<p>Les écrans changent de taille, densité et forme, mais le contenu a toujours des limites de lisibilité et l'interaction a toujours des contraintes physiques. <strong>Ce qui change :</strong> les devices, breakpoints et techniques CSS. <strong>Ce qui ne change pas :</strong> une interface doit rester lisible, actionnable et priorisée dans le contexte réel où elle est utilisée.</p>",practice:{titre:"Adapter un écran desktop au mobile",etapes:["Choisis un écran desktop dense.","Liste les éléments indispensables à la tâche principale sur mobile.","Décide ce qui reste visible, ce qui devient secondaire et ce qui est supprimé ou déplacé.","Vérifie les cibles tactiles, textes longs, clavier ouvert et ordre de lecture."],output:"Plan responsive mobile avec priorités visibles, éléments secondaires, règles d'interaction et cas de test.",critere:"Le plan est correct si la tâche principale peut être accomplie sur mobile sans zoom, sans cible minuscule et sans lecture désordonnée.",piege:"Penser le responsive comme un problème de grille uniquement. La vraie question est la priorité d'usage dans un contexte différent."},verification:["Pourquoi mobile-first aide-t-il à prioriser plutôt qu'à simplement réduire ?","Un tableau desktop de 12 colonnes doit être consulté sur mobile par des techniciens terrain. Quelles alternatives peux-tu envisager ?","Pourquoi les contraintes physiques du toucher restent-elles invariantes malgré l'évolution des frameworks ?"]})},maps:{universel:{viewBox:"0 0 820 270",nodes:[{id:"anatomieComposant",x:10,y:100,w:155,h:65},{id:"navigation",x:215,y:100,w:140,h:65},{id:"formulaires",x:405,y:40,w:120,h:65},{id:"etatsInterface",x:405,y:165,w:155,h:65},{id:"responsive",x:620,y:100,w:170,h:65}],edges:[{x1:165,y1:132,x2:213,y2:132,label:"fonde"},{x1:355,y1:112,x2:403,y2:72,label:"structure"},{x1:355,y1:150,x2:403,y2:188,label:"requiert"},{x1:525,y1:72,x2:618,y2:118,label:"adapte"},{x1:560,y1:200,x2:618,y2:152,label:"adapte"}]}}}),x=t({id:"design-D04",number:24,title:"Du Design au Code",subtitle:"Transformer les décisions de design en systèmes maintenables et implémentables",badge:"Fiche D04 — Vision Systémique",meta:["5 nœuds · universel"],readingTime:"20 min",description:"Design system, Figma, design tokens, handoff et itération design-dev comme continuité entre intention et produit réel.",accent:"systeme",nodes:{designSystem:e({id:"designSystem",label:"Le design system",icon:"⬡",kind:"systeme",niveau:"Intermédiaire",why:"Au début, chaque écran peut être ajusté à la main. Puis l'équipe grossit, les boutons divergent, les espacements changent, les messages d'erreur n'ont plus le même ton, et personne ne sait quelle version est la bonne. Un design system existe pour empêcher la cohérence de dépendre de la mémoire individuelle.",system:`Le design system synthétise les principes visuels <span class="ref-fiche">→ D02</span>, les composants et états <span class="ref-fiche">→ D03</span>, puis les relie au code via tokens <span class="ref-fiche">→ D04</span> et handoff <span class="ref-fiche">→ D04</span>. Il sert aussi la maintenance technique <span class="ref-fiche">→ P04</span> : les décisions répétées deviennent un système plutôt qu'une série d'exceptions.`,choice:"Une bibliothèque de composants documente des éléments réutilisables ; un design system ajoute règles d'usage, principes, tokens, accessibilité, gouvernance et contribution ; des brand guidelines cadrent surtout l'identité visuelle. Le bon niveau dépend de la taille de l'équipe, du nombre de produits et du coût de l'incohérence.",senior:"Un designer expérimenté commence par les composants les plus fréquents et les plus risqués, pas par un système complet abstrait. Il redoute le design system musée : beau, documenté, mais non utilisé en production. Son modèle mental : un système n'existe vraiment que si modifier une décision partagée change les écrans réels et le code réel.",errors:"<p><strong>Pattern 1 — Le musée de composants :</strong> l'équipe construit une bibliothèque parfaite hors du produit, puis personne ne l'utilise. La cause est l'envie de système avant d'avoir observé les usages répétés.</p><p><strong>Pattern 2 — La règle sans gouvernance :</strong> le système décrit des règles mais personne ne décide des exceptions, contributions et dépréciations. Ce pattern vient de la confusion entre documentation et fonctionnement organisationnel.</p><p><strong>Pattern 3 — Le composant sans contexte :</strong> le système montre l'apparence du composant mais pas quand l'utiliser, quand l'éviter, ni quels contenus sont acceptés. La cause est une focalisation sur l'objet visuel plutôt que sur la décision d'usage.</p>",invariants:"<p>Les outils de système changent, mais la cohérence à grande échelle nécessite toujours une source de vérité maintenue. <strong>Ce qui change :</strong> les plateformes, formats de documentation et bibliothèques UI. <strong>Ce qui ne change pas :</strong> sans règles partagées, maintenues et utilisées dans le produit réel, la cohérence se dégrade avec chaque écran ajouté.</p>",practice:{titre:"Définir un design system minimal",etapes:["Choisis un produit avec au moins trois écrans.","Repère les cinq décisions répétées les plus visibles : bouton, champ, couleur, espacement, message ou carte.","Pour chacune, écris la règle actuelle, l'usage prévu et l'exception acceptable.","Identifie laquelle doit devenir composant, token ou règle documentaire."],output:"Inventaire minimal de design system avec cinq décisions répétées, usage, exceptions et type de formalisation.",critere:"Le système minimal est utile si au moins une future maquette pourrait réutiliser une règle sans rediscuter la décision.",piege:"Créer un système exhaustif avant d'avoir un produit vivant. La bonne première version couvre les répétitions réelles, pas toutes les possibilités imaginables."},verification:["Quelle différence fais-tu entre une bibliothèque de composants et un design system complet ?","Ton équipe a trois styles de boutons primaires en production. Quelle première action de design system prioriserais-tu ?","Pourquoi un design system non utilisé dans le code n'est-il pas une vraie source de vérité ?"]}),figma:e({id:"figma",label:"Figma",icon:"✦",kind:"systeme",niveau:"Intermédiaire",why:`Un fichier de design peut vite devenir un grenier : anciennes pistes, maquettes finales, composants cassés, commentaires oubliés, et pages nommées "final_final". L'outil de design existe pour collaborer, mais sans structure il devient une source de confusion. Figma est puissant parce qu'il rend le design partagé ; il devient dangereux quand personne ne sait quelle page fait foi.`,system:`Figma est le lieu où les décisions de D01, D02 et D03 sont rendues visibles avant le code. Il doit rester aligné avec le design system <span class="ref-fiche">→ D04</span>, les tokens <span class="ref-fiche">→ D04</span> et le handoff <span class="ref-fiche">→ D04</span>. Il n'est pas la vérité finale seul : la vérité doit rejoindre le produit développé.`,choice:"Figma est le standard dominant pour collaboration, composants, variables, prototypes et Dev Mode ; Penpot est une alternative open source intéressante pour souveraineté et formats ouverts ; Sketch reste présent dans certains environnements macOS ; un prototype HTML peut être préférable pour interactions complexes ou contraintes techniques fortes. L'outil se choisit selon collaboration, gouvernance, intégration et nature du prototype.",senior:"Un designer expérimenté organise le fichier pour réduire l'ambiguïté : pages séparées pour exploration, ready-for-dev, composants et archive ; composants nommés selon le système ; instances utilisées plutôt que copies détachées ; versioning clair pour les décisions. Il redoute moins le fichier imparfait que le fichier où deux personnes raisonnables ne savent pas quoi implémenter.",errors:"<p><strong>Pattern 1 — Le fichier labyrinthe :</strong> les écrans finalisés côtoient explorations et archives sans statut clair. La cause est la vitesse de travail non accompagnée d'hygiène documentaire.</p><p><strong>Pattern 2 — La copie détachée :</strong> au lieu d'utiliser une instance du composant, on copie et modifie visuellement. Ce pattern vient d'un besoin local rapide qui casse la synchronisation globale.</p><p><strong>Pattern 3 — Le prototype théâtre :</strong> le prototype montre une démo fluide mais ignore états d'erreur, contenus longs et contraintes techniques. La cause est la volonté de convaincre avant de vérifier la robustesse.</p>",invariants:"<p>Les outils changent, mais la collaboration exige toujours de distinguer exploration, décision et spécification. <strong>Ce qui change :</strong> les fonctionnalités de Figma, Penpot, Sketch ou prototypes code. <strong>Ce qui ne change pas :</strong> un support de design utile doit permettre à l'équipe de savoir ce qui est exploratoire, validé, obsolète et prêt à développer.</p>",practice:{titre:"Organiser un fichier de design pour le handoff",etapes:["Prends un fichier ou imagine un fichier produit avec plusieurs écrans.","Définis quatre pages : Exploration, Ready for dev, Components, Archive.","Écris les règles de passage d'une page à l'autre et le statut attendu de chaque écran.","Nomme trois composants avec une convention stable, par exemple Button/Primary/Default."],output:"Structure de fichier avec pages, règles de statut et convention de nommage de composants.",critere:"La structure est claire si une personne nouvelle peut identifier en moins d'une minute quels écrans sont prêts à développer.",piege:"Croire que Figma résout la collaboration par défaut. L'outil rend la collaboration possible, mais l'organisation du fichier rend la collaboration fiable."},verification:["Pourquoi Figma seul ne suffit-il pas comme source de vérité produit ?","Un développeur trouve deux versions contradictoires du même écran dans le fichier. Quelle règle d'organisation manque ?","Dans quel cas un prototype HTML peut-il être plus pertinent qu'un prototype Figma ?"]}),designTokens:e({id:"designTokens",label:"Design tokens",icon:"{}",kind:"systeme",niveau:"Intermédiaire",why:"Copie une couleur en hex dans vingt fichiers et le prochain changement devient une chasse manuelle. Choisis les espacements à l'œil et chaque écran dérive légèrement. Les tokens transforment une valeur visuelle répétée en décision nommée, portable et synchronisable.",system:'Les tokens traduisent les décisions de couleur, typo et espacement de <span class="ref-fiche">→ D02</span> en valeurs utilisables par le code. Ils alimentent le design system <span class="ref-fiche">→ D04</span>, réduisent les ambiguïtés de handoff <span class="ref-fiche">→ D04</span>, et permettent aux composants <span class="ref-fiche">→ D03</span> de rester cohérents entre modes et plateformes.',choice:"Les tokens primitifs nomment une valeur brute comme blue-500 ; les tokens sémantiques nomment une intention comme color-action-primary ; les tokens de composant nomment un usage local comme button-primary-background. Les primitifs facilitent l'échelle, les sémantiques protègent le sens, les tokens de composant gèrent les exceptions. Un système mature combine les trois sans exposer les valeurs brutes partout.",senior:"Un designer expérimenté refuse les noms comme color1 ou spacing-big parce qu'ils ne survivront pas aux changements. Il anticipe mode sombre, thèmes, états, accessibilité et plateformes. Il sait qu'un bon token décrit pourquoi une valeur existe, pas seulement quelle valeur elle porte aujourd'hui.",errors:"<p><strong>Pattern 1 — Le token peinture :</strong> les tokens sont nommés par apparence immédiate, comme purpleButton, puis deviennent absurdes quand la couleur change. La cause est une nomination basée sur le présent plutôt que sur l'intention.</p><p><strong>Pattern 2 — Le hex clandestin :</strong> des valeurs directes continuent d'apparaître dans le code malgré le système de tokens. Ce pattern vient d'un système incomplet ou trop lourd, que les équipes contournent pour avancer.</p><p><strong>Pattern 3 — Le token sans usage :</strong> on crée des dizaines de tokens jamais utilisés. La cause est l'abstraction prématurée : vouloir couvrir tous les futurs possibles avant les besoins réels.</p>",invariants:"<p>Les formats de tokens évoluent, mais nommer une décision partagée reste le moyen de la maintenir. <strong>Ce qui change :</strong> les outils de synchronisation, formats JSON, variables Figma et pipelines CSS. <strong>Ce qui ne change pas :</strong> une valeur répétée sans nom finit toujours par diverger, et une valeur nommée sans intention finit par devenir incompréhensible.</p>",practice:{titre:"Créer une mini-échelle de tokens",etapes:["Choisis trois décisions visuelles répétées : couleur d'action, couleur d'erreur, espacement de section.","Définis pour chacune un token primitif, un token sémantique et un exemple d'usage composant.","Vérifie que les noms restent vrais si la valeur change.","Repère une valeur qui ne mérite pas encore de token parce qu'elle n'est pas répétée."],output:"Table de tokens avec primitif, sémantique, usage composant et justification.",critere:"Un token est bien nommé si tu peux changer sa valeur sans devoir renommer son intention.",piege:"Transformer chaque pixel en token. Un token doit représenter une décision partagée, pas une obsession de granularité."},verification:["Quelle différence fais-tu entre token primitif, token sémantique et token de composant ?","Ton produit passe en mode sombre et un token gray-900 est utilisé pour du texte, des bordures et des fonds. Quel problème cela révèle ?","Pourquoi le nom d'un token doit-il survivre à un changement de valeur ?"]}),handoff:e({id:"handoff",label:"Handoff design-dev",icon:"↔",kind:"systeme",niveau:"Intermédiaire",why:"Un développeur reçoit une maquette belle et finale, puis découvre les questions qui n'ont pas été designées : que se passe-t-il en loading, quel texte si le titre déborde, quel comportement au clavier, quel état d'erreur, quelle valeur de token ? Le handoff existe pour transformer une intention visuelle en spécification implémentable.",system:`Le handoff relie composants <span class="ref-fiche">→ D03</span>, états d'interface <span class="ref-fiche">→ D03</span>, tokens <span class="ref-fiche">→ D04</span> et contraintes techniques de la partie développement <span class="ref-fiche">→ T03</span>. Il protège l'UX de <span class="ref-fiche">→ D01</span> en évitant que les détails non spécifiés soient résolus au hasard dans le code.`,choice:"Le handoff final convient aux petits changements très cadrés ; le handoff continu implique les développeurs pendant la conception et réduit les surprises ; Storybook ou une documentation vivante permet de comparer composants design et code ; Dev Mode donne mesures et styles mais ne transmet pas seul l'intention, les règles métier et les edge cases.",senior:"Un designer expérimenté ne considère jamais le handoff comme une passation froide. Il anticipe les questions du développement : contenu long, responsive, states, accessibilité, tokens, animation, erreur réseau, permissions. Il préfère une conversation tôt avec un développeur à dix commentaires tardifs sur une maquette déjà vendue.",errors:"<p><strong>Pattern 1 — Le handoff lancer de colis :</strong> le designer livre un fichier final et disparaît. La cause est une séparation artificielle entre conception et implémentation, qui transforme les questions normales en interruptions.</p><p><strong>Pattern 2 — Le pixel sans intention :</strong> les dimensions sont fournies mais pas la raison de la décision. Ce pattern vient d'une croyance que le code reproduit des pixels, alors qu'il doit reproduire un comportement sous contraintes.</p><p><strong>Pattern 3 — L'edge case hors champ :</strong> les cas limites ne sont pas spécifiés parce qu'ils rendent la maquette moins propre. La cause est la confusion entre présentation de concept et préparation à la production.</p>",invariants:"<p>Les outils de handoff deviennent plus automatiques, mais l'intention ne se déduit jamais entièrement des pixels. <strong>Ce qui change :</strong> Dev Mode, inspecteurs, annotations et outils de documentation. <strong>Ce qui ne change pas :</strong> une implémentation fiable exige toujours de transmettre comportements, contraintes, états et priorités, pas seulement des styles.</p>",practice:{titre:"Préparer un handoff complet",etapes:["Choisis un écran prêt à développer.","Liste les composants utilisés et les tokens attendus pour couleurs, typo et espacements.","Ajoute les états : loading, empty, error, succès, focus clavier et mobile.","Écris trois questions à poser au développeur avant implémentation."],output:"Checklist de handoff avec composants, tokens, états et questions design-dev.",critere:"Le handoff est prêt si les questions restantes portent sur des choix techniques, pas sur des intentions UX non spécifiées.",piege:"Confondre inspection automatique et compréhension. Un outil peut lire une taille, pas expliquer pourquoi l'élément doit se comporter ainsi."},verification:["Pourquoi Dev Mode ne remplace-t-il pas une vraie spécification de handoff ?","Un titre peut faire 12 ou 120 caractères dans la vraie donnée. Où cette information doit-elle apparaître dans le handoff ?","Pourquoi le handoff continu réduit-il plus de risque qu'un handoff final ?"]}),iterationDesignDev:e({id:"iterationDesignDev",label:"Itération design-dev",icon:"🔄",kind:"systeme",niveau:"Intermédiaire",why:"Quand le design attend que tout soit parfait avant de parler au développement, les contraintes arrivent trop tard : animation coûteuse, composant impossible à réutiliser, performance dégradée, responsive fragile. Quand le développement implémente sans retour design, l'intention UX se dilue. L'itération design-dev existe pour faire rencontrer intention et faisabilité avant que les décisions ne soient verrouillées.",system:`L'itération design-dev ferme la boucle entre expérience visée <span class="ref-fiche">→ D01</span>, composants conçus <span class="ref-fiche">→ D03</span>, design system <span class="ref-fiche">→ D04</span> et code produit <span class="ref-fiche">→ T04</span>. Elle alimente aussi la mesure et l'apprentissage <span class="ref-fiche">→ C06</span> : le design n'est validé que quand le produit réel produit le comportement attendu.`,choice:"Le design ahead prépare un ou deux sprints d'avance pour réduire les blocages ; le design en parallèle convient aux petites équipes très synchronisées ; le pairing design-dev résout vite les interactions ambiguës ; la design QA vérifie l'implémentation réelle contre l'intention, sans tomber dans le pixel-perfect aveugle.",senior:`Un designer expérimenté sait que "pixel-perfect" est souvent une mauvaise question. Il vérifie plutôt si la hiérarchie, les états, l'accessibilité, les comportements et les intentions sont préservés dans le code. Il anticipe les compromis : parfois il faut ajuster le design pour une meilleure maintenabilité, parfois il faut défendre un détail parce qu'il porte la compréhension utilisateur.`,errors:"<p><strong>Pattern 1 — La maquette intouchable :</strong> toute contrainte technique est vécue comme une dégradation du design. La cause est l'attachement au livrable plutôt qu'à l'intention utilisateur.</p><p><strong>Pattern 2 — Le dev comme exécutant :</strong> le développeur est consulté seulement après validation, donc ses connaissances de performance, responsive et accessibilité arrivent trop tard. Ce pattern vient d'une séparation hiérarchique des métiers.</p><p><strong>Pattern 3 — La QA cosmétique :</strong> la revue se limite à comparer les pixels, sans vérifier les états, le clavier, les données réelles ou les erreurs. La cause est que le visible immédiat attire plus l'attention que le comportement systémique.</p>",invariants:"<p>Les méthodes de production changent, mais une interface réelle est toujours le résultat d'un compromis entre intention, contrainte et usage observé. <strong>Ce qui change :</strong> les cycles de sprint, outils de QA, frameworks frontend et modes de collaboration. <strong>Ce qui ne change pas :</strong> design et code doivent itérer ensemble pour préserver l'expérience quand elle rencontre les contraintes du produit réel.</p>",practice:{titre:"Structurer une revue design-dev",etapes:["Choisis une fonctionnalité en cours ou imagine une fonctionnalité prête à intégrer.","Prépare une liste de vérification : hiérarchie, états, responsive, accessibilité, tokens, données longues, performance perçue.","Décide quels points doivent être testés dans le navigateur plutôt que dans la maquette.","Formule trois compromis acceptables et trois éléments à défendre absolument."],output:"Plan de revue design-dev avec checklist, tests navigateur, compromis et points non négociables.",critere:"La revue est utile si elle distingue clairement un écart cosmétique, un écart d'intention UX et une contrainte technique légitime.",piege:"Utiliser la revue design-dev comme tribunal de conformité. Le but est d'améliorer le produit réel, pas de prouver que la maquette avait toujours raison."},verification:["Pourquoi le pixel-perfect strict peut-il être une mauvaise métrique de qualité ?","Un développeur explique qu'une animation prévue coûte trop cher en performance sur mobile. Comment raisonnes-tu le compromis ?","Pourquoi l'expérience réelle ne peut-elle pas être validée uniquement dans Figma ?"]})},maps:{universel:{viewBox:"0 0 820 270",nodes:[{id:"designSystem",x:10,y:100,w:140,h:65},{id:"figma",x:200,y:100,w:100,h:65},{id:"designTokens",x:355,y:40,w:130,h:65},{id:"handoff",x:355,y:165,w:120,h:65},{id:"iterationDesignDev",x:555,y:100,w:175,h:65}],edges:[{x1:150,y1:132,x2:198,y2:132,label:"structure"},{x1:300,y1:112,x2:353,y2:72,label:"génère"},{x1:300,y1:150,x2:353,y2:188,label:"organise"},{x1:485,y1:72,x2:553,y2:118,label:"alimente"},{x1:475,y1:200,x2:553,y2:150,label:"alimente"}]}}}),L=[h,q,b,x];export{L as d};
